cd /workspace && python3 - <<'PY'
import sys,random,time
sys.path.insert(0,'/workspace/submission');sys.path.insert(0,'/workspace/tmp')
from compiler import compile_plan, find_deficient_cut
from compiler_proto import validate_plan
random.seed(31337)
t0=time.time();prep=den=0
for it in range(1000):
 n=random.choice([16,24,32,48]); np=random.choice([4,8,16,24,32]);np=min(np,n)
 C=sorted(random.sample(range(n),np))
 roots={v:random.choice([0,1,2,5,20]) for v in C}
 if sum(roots.values())==0:roots[C[0]]=1
 D=sum(roots.values())
 links=[]
 # backbone
 for v in range(1,n):
  u=random.randrange(v);links.append((u,v) if random.random()<.5 else (v,u))
 # random extras up to128
 try:
  used={tuple(sorted(e)) for e in links}
 except:used=set()
 poss=[]
 for u in range(n):
  for v in range(u+1,n):
   if (u,v) not in used:poss.append((u,v))
 random.shuffle(poss)
 while len(links)<128 and poss:links.append(poss.pop())
 # For mostly feasible use capacities high random, sometimes low
 env={i:random.choice([D,D*2,D*5,random.randint(1,max(1,3*D))]) if random.random()<.8 else random.choice([0,1,2]) for i in range(len(links))}
 p=random.choice([1,2,3])
 cut=find_deficient_cut(n,links,C,roots,p,env)
 t=time.time()
 try:
  out,payload=compile_plan(n,links,C,roots,p,env)
  if cut is not None:
   assert out=='denied';den+=1
  else:
   assert out=='prepared',(out,payload)
   validate_plan(payload,n,links,C,roots,p,env);prep+=1
  if it%100==0:print(it,'prep',prep,'den',den,'case time',round(time.time()-t,2),'total',round(time.time()-t0,2),flush=True)
 except Exception as e:
  print('FAIL',it,n,np,C,roots,links,env,p,'cut',cut,repr(e));raise
print('DONE',prep,den,time.time()-t0)
